  "settings.commandline.trustHint": "Permet à l’outil en ligne de commande de se connecter sans s’authentifier.",
  "settings.commandline.trustCaution": "Dans ce mode, tout programme sur les machines autorisées, y compris les agents exécutés ici, peut contrôler Polyth en votre nom et approuver des actions d’agents. Les requêtes via un proxy inverse ou depuis un navigateur ne sont jamais approuvées. « Réseau privé » désigne les adresses réseau locales (10.x, 172.16–31.x, 192.168.x), et non les plages VPN ou réseau superposé.",
