  "shellintro.kicker": "Visite de l’interface",
  "shellintro.stepCount": "{step} sur {total}",
  "shellintro.steps": "Étapes de la visite",
  "shellintro.goToStep": "Aller à l’étape {step} sur {total}",
  "shellintro.start": "Faire le tour",
  "shellintro.skip": "Passer la visite",
  "shellintro.finish": "Commencer",
  "shellintro.menuEntry": "Visite de l’interface",
  "shellintro.addProjectNow": "Ajouter un projet maintenant",
  "shellintro.addProjectResumeNote": "La visite reprendra quand vous aurez terminé.",
  "shellintro.projectReadyTitle": "Votre projet est prêt",
  "shellintro.projectReadyBody": "Le voici. Tant qu’il est sélectionné, les nouvelles discussions peuvent voir ses fichiers et travailler avec. Cliquez sur un projet dans cette liste pour passer de l’un à l’autre.",
  "shellintro.projectReadyPhoneBody": "Il est maintenant dans ce menu. Tant qu’il est sélectionné, les nouvelles discussions peuvent voir ses fichiers et travailler avec. Touchez ici à tout moment pour changer de projet.",
  "shellintro.openAppearance": "Ouvrir Apparence",
  "shellintro.welcomeTitle": "Bienvenue dans Polyth",
  "shellintro.welcomeBody": "Vous pouvez commencer tout de suite : il n’y a rien à configurer, et vous ne pouvez rien casser. Cette visite d’une minute vous montre où écrire, où sont gardées vos discussions et comment changer les choses plus tard.",
  "shellintro.startTitle": "Commencez ici",
  "shellintro.startBody": "Écrivez ce dont vous avez besoin avec vos propres mots – une question, une tâche ou un brouillon – puis envoyez. La réponse apparaît juste ici. Vous seul voyez vos discussions.",
  "shellintro.projectsTitle": "Discussions et projets",
  "shellintro.projectsBody": "Toutes vos discussions sont rangées ici, pour que vous puissiez revenir à n’importe laquelle. Les projets que vous ajouterez plus tard apparaîtront ici aussi, chacun avec ses discussions. Un petit point indique que l’assistant travaille ou attend votre réponse.",
  "shellintro.addProjectTitle": "Des projets, quand vous en aurez besoin",
  "shellintro.addProjectBody": "Inutile pour commencer. Un projet, c’est simplement un dossier avec vos fichiers – documents, photos, site web ou code. Ajoutez-en un, et l’assistant pourra ouvrir et modifier ces fichiers sur votre demande. (Les développeurs peuvent aussi connecter un dépôt Git ou un autre ordinateur en SSH.)",
  "shellintro.topRailTitle": "Les outils en haut",
  "shellintro.topRailBody": "Des boutons pour vos outils. Chacun s’ouvre à côté de la discussion, qui reste visible.",
  "shellintro.rightRailTitle": "Plus d’outils sur le côté",
  "shellintro.rightRailBody": "Plus d’outils, y compris les modules complémentaires que vous installez. Chacun s’ouvre en panneau latéral ; faites glisser son bord pour l’élargir.",
  "shellintro.toolsTitle": "Outils",
  "shellintro.dragTitle": "Placez les boutons où vous voulez",
  "shellintro.dragBody": "Faites glisser un bouton pour le déplacer le long de sa barre ou sur une autre. Pour le retirer, éloignez-le et relâchez – vous pourrez le remettre plus tard. Sur écran tactile, maintenez d’abord le doigt appuyé.",
  "shellintro.customizeTitle": "Des fonctions à votre façon",
  "shellintro.customizeBody": "Ouvrez le menu que montre la flèche et activez le « Mode édition » : un crayon apparaît sur chaque partie de l’écran, pour ajouter, retirer ou déplacer des boutons et des widgets. Les Paramètres contiennent le reste : assistants et modèles d’IA, modules complémentaires (paquets) et raccourcis clavier.",
  "shellintro.appearanceTitle": "Une apparence à votre goût",
  "shellintro.appearanceBody": "Dans Paramètres → Apparence, choisissez les couleurs, le mode clair ou sombre, la taille du texte, les polices, un fond d’écran et plus encore. Chaque projet peut aussi avoir sa propre icône.",
  "shellintro.projectsPhoneTitle": "Discussions et projets",
  "shellintro.projectsPhoneBody": "Touchez ici pour voir vos discussions. Les projets ajoutés plus tard apparaîtront ici aussi. Un petit point indique que l’assistant travaille ou attend votre réponse.",
  "shellintro.addProjectPhoneBody": "Inutile pour commencer. Un projet, c’est simplement un dossier avec vos fichiers – documents, photos, site web ou code. Le bouton + de ce menu en ajoute un ; l’assistant pourra alors ouvrir et modifier ces fichiers sur votre demande.",
  "shellintro.toolsPhoneTitle": "Outils",
  "shellintro.toolsPhoneBody": "Vos outils sont ici. Chacun s’ouvre en plein écran ; touchez Retour pour revenir à la discussion.",
  "shellintro.customizePhoneBody": "Sur un ordinateur, le « Mode édition » de votre menu permet d’ajouter, retirer ou déplacer des boutons. Ici aussi, les Paramètres permettent de choisir les assistants et modèles d’IA, les modules complémentaires (paquets) et plus encore.",
  "composer.manageHarnesses": "Gérer les harnesses",
  "packages.onboarding.tours.installed.modelsComeFromHarnesses": "Les modèles viennent de vos harness",
  "packages.onboarding.tours.installed.polythTalksToModelsThroughHarnesses": "Polyth dialogue avec les modèles via des harnesses d’agents. Les modèles gratuits d’OpenCode fonctionnent sans compte. Vous préférez Claude Code, Codex ou un autre agent ? Installez et configurez vos favoris sur la page Harnesses — c’est facultatif.",
  "packages.onboarding.tours.installed.openHarnesses": "Ouvrir Harnesses",
  "desktopupdate.availableTitle": "Polyth {version} est disponible",
